-- scripts/build19_check2.sql (build 19): check 2 (a)-(m) per CLAUDE.md section 9 for HHG, HERSHA, DAVIDSON, JW_VENICE. Read-only. Every count must be 0.
select 'a' c, source_lane l, count(*) n from (select source_lane, source_site_code, department, account_key, record_type from DEV_G2M_AI.XREF_SNAPSHOT.XREF_ACCOUNT_CLASSIFICATION where source_lane in ('HHG','HERSHA','DAVIDSON','JW_VENICE') group by all having count(*)>1) group by 2
