select 'c', 'JW_VENICE', count(*) from (select source_site_code, department, account_key, record_type from DEV_G2M_AI.STAGING.STG_JW_VENICE_FCAST_ACT_FORECAST union all select source_site_code, department, account_key, record_type from DEV_G2M_AI.STAGING.STG_JW_VENICE_FCAST_BY_PERIOD union all select source_site_code, department, account_key, record_type from DEV_G2M_AI.STAGING.STG_JW_VENICE_FTE union all select source_site_code, department, account_key, record_type from DEV_G2M_AI.STAGING.STG_JW_VENICE_HEADCOUNT union all select source_site_code, department, account_key, record_type from DEV_G2M_AI.STAGING.STG_JW_VENICE_MONTHLY_PL_DEPT union all select source_site_code, department, account_key, record_type from DEV_G2M_AI.STAGING.STG_JW_VENICE_CAPEX) s where not exists (select 1 from DEV_G2M_AI.XREF_SNAPSHOT.XREF_ACCOUNT_CLASSIFICATION x where x.source_lane='JW_VENICE' and x.source_site_code=coalesce(nullif(trim(s.source_site_code),''),'~BLANK~') and x.department=coalesce(nullif(trim(s.department),''),'~BLANK~') and x.account_key=coalesce(nullif(trim(s.account_key),''),'~BLANK~') and x.record_type=coalesce(nullif(trim(s.record_type),''),'~BLANK~'))
