select 'm', 'HHG', count(*) from (select source_site_code, account_key, period_end, category, scenario from (select source_lane, source_site_code, account_key, period_end, category, scenario, source_table from DEV_G2M_AI.SEMANTIC.SEM_AI_INCOME_STATEMENT_ACTUAL union all select source_lane, source_site_code, account_key, period_end, category, scenario, source_table from DEV_G2M_AI.SEMANTIC.SEM_AI_INCOME_STATEMENT_FORECAST union all select source_lane, source_site_code, account_key, period_end, category, scenario, source_table from DEV_G2M_AI.SEMANTIC.SEM_AI_INCOME_STATEMENT_BUDGET) where source_lane='HHG' and source_table like '%FORECAST_VERSIONS' group by all having count(*)>1)
union all
select 'm', 'JW_VENICE', count(*) from (select source_lane, source_site_code, account_key, period_end, category, scenario, source_table from DEV_G2M_AI.SEMANTIC.SEM_AI_INCOME_STATEMENT_ACTUAL union all select source_lane, source_site_code, account_key, period_end, category, scenario, source_table from DEV_G2M_AI.SEMANTIC.SEM_AI_INCOME_STATEMENT_FORECAST union all select source_lane, source_site_code, account_key, period_end, category, scenario, source_table from DEV_G2M_AI.SEMANTIC.SEM_AI_INCOME_STATEMENT_BUDGET) where source_lane='JW_VENICE' and source_table like '%FIN_PL_SUMMARY' and category='ACTUAL' and period_end in ('2025-08-31'::date,'2026-08-31'::date)
order by 1, 2;
